/**
 * Deterministic hard-compatibility validation engine (Phase 3).
 *
 * Every candidate outfit—whether generated by the internal engine or proposed by Gemini—must pass
 * `validateOutfit` before it can be scored or shown to the user.
 *
 * Three tiers:
 *  - Level 1 (`hard`): objective incompatibilities, structural errors, ownership/eligibility failures,
 *    violated mandatory constraints, or severe dress-code / climate contradictions. Any Level 1
 *    violation rejects the outfit immediately and cannot be rescued by a high aggregate score.
 *  - Level 2 (`warnings`): questionable colour clashes, competing patterns, silhouette imbalance,
 *    excessive layering, or aesthetic tension. Rejected when cumulative warning load exceeds the
 *    threshold (relaxed when the user explicitly requests a bold/experimental look or streetwear).
 *  - Level 3 (soft preferences): handled in `scorer.ts` to rank valid outfits.
 */
import { colourInfo, readPalette } from "@/lib/styling/colour";
import { matchesForbidden } from "@/lib/styling/constraints";
import { CASUAL_ONLY_BOTTOMS, FORMAL_TYPES, isReliable, profileGarment, typeLabel } from "@/lib/styling/taxonomy";
import type {
  GarmentProfile,
  OutfitArchetype,
  ValidationContext,
  ValidationResult,
  Violation,
} from "@/lib/styling/types";
import { isEligibleStatus } from "@/lib/wardrobe/status";

function hard(code: string, message: string, itemIds: string[] = []): Violation {
  return { level: 1, code, message, severity: 3, itemIds };
}

function warn(code: string, message: string, severity: 1 | 2 | 3, itemIds: string[] = []): Violation {
  return { level: 2, code, message, severity, itemIds };
}

/** Determine the structural archetype of a set of garment profiles. */
export function inferArchetype(profiles: GarmentProfile[], allowPartial: boolean): OutfitArchetype {
  const tops = profiles.filter((p) => p.role === "top");
  const bottoms = profiles.filter((p) => p.role === "bottom");
  const onepieces = profiles.filter((p) => p.role === "onepiece");

  if (onepieces.some((p) => p.type === "traditional_set") || tops.some((p) => p.type === "traditional_top")) {
    return "traditional";
  }
  if (onepieces.length === 1 && bottoms.length === 0) {
    return "onepiece";
  }
  if (tops.length >= 1 && bottoms.length === 1 && onepieces.length === 0) {
    return "standard";
  }
  if (allowPartial && profiles.length >= 1) {
    return "partial";
  }
  return "unknown";
}

/**
 * Validates a proposed list of item IDs against ownership, availability, outfit structure,
 * garment compatibility, dress code, climate, and explicit user constraints.
 */
export function validateOutfit(
  itemIds: string[],
  ctx: ValidationContext,
  profilesById?: ReadonlyMap<string, GarmentProfile>,
): ValidationResult {
  const hardViolations: Violation[] = [];
  const warnings: Violation[] = [];

  if (!itemIds || itemIds.length === 0) {
    hardViolations.push(hard("EMPTY_OUTFIT", "Outfit contains no items."));
    return { ok: false, archetype: "unknown", hard: hardViolations, warnings, warningLoad: 0 };
  }

  // 1. Duplicate item IDs
  const seenIds = new Set<string>();
  for (const id of itemIds) {
    if (seenIds.has(id)) {
      hardViolations.push(hard("DUPLICATE_ITEM_ID", "Outfit repeats the same item more than once.", [id]));
    }
    seenIds.add(id);
  }

  // 2. Ownership & eligibility checks
  const profiles: GarmentProfile[] = [];
  for (const id of seenIds) {
    const item = ctx.owned.get(id);
    if (!item) {
      hardViolations.push(hard("UNOWNED_ITEM", `Item ${id} does not belong to the user's wardrobe.`, [id]));
      continue;
    }
    if (!isEligibleStatus(item.status, ctx.allowRewearWorn)) {
      hardViolations.push(
        hard("INELIGIBLE_STATUS", `"${item.name}" is currently ${item.status} and cannot be worn.`, [id]),
      );
    }
    const p = profilesById?.get(id) ?? profileGarment(item);
    profiles.push(p);
  }

  if (profiles.length === 0) {
    return { ok: false, archetype: "unknown", hard: hardViolations, warnings, warningLoad: 0 };
  }

  // 3. Excluded / uncertain garment classifications
  for (const p of profiles) {
    if (!p.usable) {
      hardViolations.push(
        hard("UNUSABLE_GARMENT_ROLE", `"${p.item.name}" (${typeLabel(p.type)}) cannot be used as an outfit garment.`, [p.id]),
      );
    } else if (!isReliable(p) && ["top", "bottom", "onepiece", "shoes"].includes(p.role)) {
      hardViolations.push(
        hard(
          "UNCERTAIN_CLASSIFICATION",
          `"${p.item.name}" has conflicting or uncertain category metadata and cannot fill an essential role until reviewed.`,
          [p.id],
        ),
      );
    }
  }

  const tops = profiles.filter((p) => p.role === "top");
  const bottoms = profiles.filter((p) => p.role === "bottom");
  const onepieces = profiles.filter((p) => p.role === "onepiece");
  const outers = profiles.filter((p) => p.role === "outer");
  const shoes = profiles.filter((p) => p.role === "shoes");
  const accessories = profiles.filter((p) => p.role === "accessory");

  const allowPartial = ctx.allowPartial || ctx.constraints.wantsPartial;
  const archetype = inferArchetype(profiles, allowPartial);

  // 4. Structural validation
  if (onepieces.length > 1) {
    hardViolations.push(
      hard("MULTIPLE_ONEPIECE", "Cannot combine multiple dresses or one-piece garments in one outfit.", onepieces.map((p) => p.id)),
    );
  }

  if (onepieces.length >= 1 && bottoms.length >= 1) {
    hardViolations.push(
      hard(
        "ONEPIECE_WITH_BOTTOM",
        `Cannot pair "${onepieces[0].item.name}" with "${bottoms[0].item.name}" as competing primary garments.`,
        [onepieces[0].id, bottoms[0].id],
      ),
    );
  }

  if (onepieces.length >= 1 && tops.length >= 1) {
    // Only layering tops (cardigan, sweater) may sit over a dress; base tees/shirts conflict.
    const nonLayeringTop = tops.find((t) => !t.layering);
    if (nonLayeringTop) {
      hardViolations.push(
        hard(
          "ONEPIECE_WITH_BASE_TOP",
          `Cannot combine "${onepieces[0].item.name}" with non-layering top "${nonLayeringTop.item.name}".`,
          [onepieces[0].id, nonLayeringTop.id],
        ),
      );
    }
  }

  if (bottoms.length > 1) {
    hardViolations.push(
      hard("MULTIPLE_BOTTOMS", "Outfit contains more than one bottom garment.", bottoms.map((p) => p.id)),
    );
  }

  if (shoes.length > 1) {
    hardViolations.push(
      hard("MULTIPLE_FOOTWEAR", "Outfit contains multiple pairs of footwear.", shoes.map((p) => p.id)),
    );
  }

  // Tops layering: at most 2 tops, and only if one is a layering piece (sweater, cardigan, hoodie) over a base top.
  if (tops.length > 2) {
    hardViolations.push(hard("EXCESSIVE_TOPS", "Too many top layers in a single outfit.", tops.map((p) => p.id)));
  } else if (tops.length === 2) {
    const layeringCount = tops.filter((t) => t.layering).length;
    const bothSameType = tops[0].type === tops[1].type;
    if (layeringCount === 0 || bothSameType) {
      hardViolations.push(
        hard(
          "INCOMPATIBLE_TOP_LAYERS",
          `Cannot wear "${tops[0].item.name}" and "${tops[1].item.name}" together as competing base tops.`,
          [tops[0].id, tops[1].id],
        ),
      );
    }
  }

  if (outers.length > 1) {
    hardViolations.push(
      hard("MULTIPLE_OUTERWEAR", "Outfit contains multiple competing outerwear pieces.", outers.map((p) => p.id)),
    );
  }

  // Competing accessories (e.g. two bags, two belts, two watches, two hats/caps)
  const bags = accessories.filter((a) => a.type === "bag");
  if (bags.length > 1) {
    hardViolations.push(hard("MULTIPLE_BAGS", "Outfit includes two competing bags.", bags.map((a) => a.id)));
  }
  const belts = accessories.filter((a) => a.type === "belt");
  if (belts.length > 1) {
    hardViolations.push(hard("MULTIPLE_BELTS", "Outfit includes more than one belt.", belts.map((a) => a.id)));
  }
  const watches = accessories.filter((a) => a.type === "watch");
  if (watches.length > 1) {
    hardViolations.push(hard("MULTIPLE_WATCHES", "Outfit includes more than one watch.", watches.map((a) => a.id)));
  }
  const headwear = accessories.filter((a) => a.type === "hat" || a.type === "cap");
  if (headwear.length > 1) {
    hardViolations.push(hard("MULTIPLE_HEADWEAR", "Outfit includes multiple hats/caps.", headwear.map((a) => a.id)));
  }

  // Completeness check (unless partial is allowed)
  if (!allowPartial) {
    if (archetype === "unknown") {
      hardViolations.push(
        hard("INCOMPLETE_STRUCTURE", "Complete outfit requires either a top and bottom, or a one-piece garment."),
      );
    }
    if (shoes.length === 0) {
      // Check if user owns any eligible footwear; if they do, omitting footwear is a structural failure.
      const hasAnyEligibleShoes = [...ctx.owned.values()].some(
        (i) => isEligibleStatus(i.status, ctx.allowRewearWorn) && profileGarment(i).role === "shoes",
      );
      if (hasAnyEligibleShoes) {
        hardViolations.push(hard("MISSING_FOOTWEAR", "Complete outfit must include footwear when eligible shoes are available."));
      }
    }
  }

  // 5. Garment-pair incompatibility rules
  const bottom = bottoms[0];
  const shoe = shoes[0];
  const primaryTop = tops[0];

  // Belt with non-belted bottoms (joggers, sweatpants, leggings, athletic shorts) or dress without reason
  if (belts.length > 0 && bottom && ["joggers", "leggings", "athletic_shorts"].includes(bottom.type)) {
    hardViolations.push(
      hard("BELT_WITH_ELASTIC_WAIST", `Cannot pair a belt with elastic-waist "${bottom.item.name}".`, [belts[0].id, bottom.id]),
    );
  }

  // Tie with t-shirt, tank top, hoodie, or athletic top
  const ties = accessories.filter((a) => a.type === "tie");
  if (ties.length > 0 && primaryTop && ["t_shirt", "tank_top", "crop_top", "hoodie", "athletic_top"].includes(primaryTop.type)) {
    hardViolations.push(
      hard("TIE_WITHOUT_COLLARED_SHIRT", `A tie cannot be worn with "${primaryTop.item.name}".`, [ties[0].id, primaryTop.id]),
    );
  }

  // Formal blazer/suit jacket with athletic shorts or gym leggings
  if (outers.some((o) => o.type === "blazer") && bottom && ["athletic_shorts", "joggers", "leggings"].includes(bottom.type)) {
    const blazer = outers.find((o) => o.type === "blazer")!;
    hardViolations.push(
      hard("BLAZER_WITH_GYM_BOTTOM", `Structured blazer "${blazer.item.name}" clashes with "${bottom.item.name}".`, [blazer.id, bottom.id]),
    );
  }

  // Dress shoes with athletic shorts, jorts, or joggers
  if (shoe?.type === "dress_shoes" && bottom && ["shorts", "jorts", "athletic_shorts", "joggers", "leggings"].includes(bottom.type)) {
    hardViolations.push(
      hard("DRESS_SHOES_WITH_CASUAL_SHORT_OR_JOGGER", `Formal dress shoes "${shoe.item.name}" are incompatible with "${bottom.item.name}".`, [shoe.id, bottom.id]),
    );
  }

  // 6. Dress-code alignment
  const dc = ctx.constraints.dressCode;
  const wantsSporty = dc === "athletic" || (ctx.constraints.styles.includes("sporty") && !ctx.constraints.styles.includes("smart_casual"));

  if (dc === "formal") {
    for (const p of profiles) {
      if (
        CASUAL_ONLY_BOTTOMS.has(p.type) ||
        ["t_shirt", "tank_top", "crop_top", "hoodie", "athletic_top", "slides", "sandals", "sneakers", "windbreaker", "track_jacket", "cap"].includes(p.type)
      ) {
        hardViolations.push(
          hard("FORMAL_DRESS_CODE_VIOLATION", `"${p.item.name}" (${typeLabel(p.type)}) is too casual for a formal dress code.`, [p.id]),
        );
      }
    }
  } else if (dc === "business") {
    for (const p of profiles) {
      if (
        ["shorts", "jorts", "athletic_shorts", "joggers", "leggings", "cargo_pants", "tank_top", "crop_top", "hoodie", "athletic_top", "slides", "sandals", "cap", "track_jacket", "windbreaker"].includes(p.type)
      ) {
        hardViolations.push(
          hard("BUSINESS_DRESS_CODE_VIOLATION", `"${p.item.name}" (${typeLabel(p.type)}) is inappropriate for an office/business setting.`, [p.id]),
        );
      }
    }
  } else if (dc === "worship") {
    for (const p of profiles) {
      if (["athletic_shorts", "jorts", "shorts", "crop_top", "tank_top", "slides"].includes(p.type)) {
        hardViolations.push(
          hard("WORSHIP_DRESS_CODE_VIOLATION", `"${p.item.name}" is too casual for worship/service.`, [p.id]),
        );
      }
    }
  }

  if (wantsSporty) {
    for (const p of profiles) {
      const isAnchored = ctx.constraints.anchorGroups.some((g) => g.includes(p.id));
      if (isAnchored) continue;

      const invalidSportyType =
        FORMAL_TYPES.has(p.type) ||
        ["jeans", "skirt", "dress", "jumpsuit", "traditional_set", "traditional_top", "blouse", "cardigan", "boots", "flats", "sandals", "slides", "belt", "scarf"].includes(p.type) ||
        (p.type === "jorts" && !p.athletic) ||
        (p.type === "generic_trousers" && !p.athletic) ||
        (p.type === "shirt" && !p.athletic) ||
        (p.type === "generic_shoes" && !p.athletic) ||
        (dc === "athletic" && ["cargo_pants", "capri_pants"].includes(p.type) && !p.athletic);

      if (invalidSportyType) {
        hardViolations.push(
          hard(
            "ATHLETIC_DRESS_CODE_VIOLATION",
            `"${p.item.name}" (${typeLabel(p.type)}) is not suitable for a sporty/athletic look.`,
            [p.id],
          ),
        );
      }
    }
  }

  // 7. Weather & climate suitability
  const temp = ctx.weather?.temperatureC ?? (ctx.constraints.hotHint ? 32 : null);
  const isHot = (temp !== null && temp >= 28) || ctx.constraints.hotHint;
  const isVeryHot = (temp !== null && temp >= 30) || ctx.constraints.hotHint;
  const isCold = temp !== null && temp <= 13;

  if (isHot) {
    for (const p of profiles) {
      if (p.type === "coat" || (p.warmth !== null && p.warmth >= 5)) {
        hardViolations.push(
          hard("HOT_WEATHER_HEAVY_COAT", `"${p.item.name}" is far too warm for hot weather (${temp ?? 30}°C).`, [p.id]),
        );
      } else if (isVeryHot && (["hoodie", "sweater", "scarf"].includes(p.type) || (p.warmth !== null && p.warmth >= 4))) {
        // Unless explicitly anchored by the user
        const isAnchored = ctx.constraints.anchorGroups.some((g) => g.includes(p.id));
        if (!isAnchored) {
          hardViolations.push(
            hard("HOT_WEATHER_WARM_GARMENT", `"${p.item.name}" is too warm for ${temp ?? 30}°C heat.`, [p.id]),
          );
        }
      }
    }
    if (outers.length > 0 && tops.some((t) => t.layering)) {
      hardViolations.push(
        hard("HOT_WEATHER_HEAVY_LAYERING", "Layering outerwear over a warm mid-layer is unsuitable for hot weather.", [
          ...outers.map((o) => o.id),
          ...tops.filter((t) => t.layering).map((t) => t.id),
        ]),
      );
    } else if (isVeryHot && outers.length > 0 && dc !== "formal" && dc !== "business") {
      const outer = outers[0];
      const isAnchored = ctx.constraints.anchorGroups.some((g) => g.includes(outer.id));
      if (!isAnchored) {
        warnings.push(warn("HOT_WEATHER_OUTERWEAR", `"${outer.item.name}" may feel warm in ${temp ?? 30}°C weather.`, 2, [outer.id]));
      }
    }
  }

  if (isCold && outers.length === 0 && !tops.some((t) => (t.warmth ?? 2) >= 3)) {
    if (profiles.some((p) => p.length === "short" || ["tank_top", "crop_top", "shorts", "jorts", "sandals", "slides"].includes(p.type))) {
      warnings.push(warn("COLD_WEATHER_EXPOSED", `Light summer pieces without warm layers may be too cold for ${temp}°C.`, 2));
    }
  }

  // 8. Explicit user constraints (anchors, forbidden rules, mandatory palette, required colours)
  const idSet = new Set(profiles.map((p) => p.id));
  for (const group of ctx.constraints.anchorGroups) {
    if (group.length > 0 && !group.some((id) => idSet.has(id))) {
      hardViolations.push(
        hard("MISSING_ANCHOR_ITEM", "Outfit does not include the requested anchor garment.", group),
      );
    }
  }

  for (const p of profiles) {
    for (const rule of ctx.constraints.forbidden) {
      if (matchesForbidden(rule, p)) {
        hardViolations.push(
          hard("FORBIDDEN_GARMENT", `"${p.item.name}" violates your constraint ("${rule.phrase}").`, [p.id]),
        );
      }
    }
  }

  const coreProfiles = profiles.filter((p) => ["top", "bottom", "onepiece", "outer", "shoes"].includes(p.role));
  if (ctx.constraints.palette) {
    const pal = ctx.constraints.palette;
    if (pal.mode === "single") {
      const target = pal.colours[0];
      for (const p of coreProfiles) {
        if (!p.colour || p.colour !== target) {
          hardViolations.push(
            hard("PALETTE_VIOLATION", `"${p.item.name}" (${p.colour ?? "unknown colour"}) does not match the requested ${pal.label} palette.`, [p.id]),
          );
        }
      }
    } else if (pal.mode === "monochrome") {
      const knownColours = [...new Set(coreProfiles.map((p) => p.colour).filter((c): c is string => Boolean(c)))];
      if (knownColours.length > 1) {
        hardViolations.push(
          hard("MONOCHROME_VIOLATION", `Monochrome outfit requires a single colour family, but mixes ${knownColours.join(" and ")}.`),
        );
      }
    }
  }

  for (const reqCol of ctx.constraints.requiredColours) {
    if (!profiles.some((p) => p.colour === reqCol || p.item.secondaryColours.map((c) => c.toLowerCase()).includes(reqCol))) {
      hardViolations.push(
        hard("MISSING_REQUIRED_COLOUR", `Outfit does not include any ${reqCol} piece as requested.`),
      );
    }
  }

  if (ctx.constraints.minDaysSinceWorn !== null) {
    const cutoffMs = Date.now() - ctx.constraints.minDaysSinceWorn * 86_400_000;
    for (const p of profiles) {
      if (p.item.lastWornAt && new Date(p.item.lastWornAt).getTime() > cutoffMs) {
        const isAnchored = ctx.constraints.anchorGroups.some((g) => g.includes(p.id));
        if (!isAnchored) {
          hardViolations.push(
            hard("RECENTLY_WORN_ITEM", `"${p.item.name}" was worn recently and you asked for unworn/rested clothes.`, [p.id]),
          );
        }
      }
    }
  }

  // 9. Level 2 — Strong compatibility warnings (colour, pattern, silhouette, formality gap)
  const paletteReading = readPalette(coreProfiles.map((p) => p.colour));
  if (paletteReading.clashSeverity >= 3) {
    warnings.push(warn("COLOUR_CLASH_SEVERE", `Competing accent colours (${paletteReading.chromaticFamilies.join(", ")}) create visual clutter.`, 3));
  } else if (paletteReading.clashSeverity === 2) {
    warnings.push(warn("COLOUR_CONTRAST_TENSION", `Bold colour contrast (${paletteReading.chromaticFamilies.join(" with ")}) needs intentional styling.`, 2));
  }

  // Pattern competition
  const patterned = coreProfiles.filter((p) => p.pattern && p.pattern !== "solid");
  if (patterned.length >= 3) {
    warnings.push(
      warn("EXCESSIVE_PATTERNS", "Three or more patterned pieces compete visually.", 3, patterned.map((p) => p.id)),
    );
  } else if (patterned.length === 2) {
    const [a, b] = patterned;
    const loudPatterns = new Set(["floral", "graphic", "plaid", "camouflage", "polka_dot", "printed"]);
    const bothLoud = loudPatterns.has(a.pattern!) && loudPatterns.has(b.pattern!);
    const sharesColour = a.colour && b.colour && (a.colour === b.colour || colourInfo(a.colour)?.neutral || colourInfo(b.colour)?.neutral);
    if (bothLoud && !sharesColour) {
      warnings.push(
        warn("COMPETING_PATTERNS", `Patterned "${a.item.name}" (${a.pattern}) and "${b.item.name}" (${b.pattern}) compete without a shared colour anchor.`, 3, [a.id, b.id]),
      );
    } else if (a.pattern === b.pattern && a.type !== "traditional_set") {
      warnings.push(
        warn("MIXED_PATTERNS", `Mixing two ${a.pattern} pieces works best when scale or colour is intentionally contrasted.`, 1, [a.id, b.id]),
      );
    }
  }

  // Formality gap between top and bottom
  if (primaryTop && bottom) {
    const gap = Math.abs(primaryTop.formality - bottom.formality);
    if (gap >= 3) {
      warnings.push(
        warn(
          "FORMALITY_MISMATCH",
          `Large formality gap between "${primaryTop.item.name}" and "${bottom.item.name}".`,
          3,
          [primaryTop.id, bottom.id],
        ),
      );
    } else if (gap === 2 && primaryTop.type === "dress_shirt" && ["shorts", "jorts", "joggers", "cargo_pants"].includes(bottom.type)) {
      warnings.push(
        warn(
          "FORMAL_SHIRT_CASUAL_BOTTOM",
          `Formal "${primaryTop.item.name}" with casual "${bottom.item.name}" can look mismatched unless styled open or relaxed.`,
          2,
          [primaryTop.id, bottom.id],
        ),
      );
    }
  }

  // Silhouette balance
  const isStreetwearContext =
    ctx.constraints.styles.includes("streetwear") ||
    ctx.constraints.styles.includes("y2k") ||
    profiles.some((p) => p.item.style === "streetwear");

  if (primaryTop && bottom) {
    if (primaryTop.silhouette === "oversized" && (bottom.silhouette === "wide" || bottom.silhouette === "oversized")) {
      if (!isStreetwearContext && !ctx.constraints.allowBold) {
        warnings.push(
          warn("VOLUMINOUS_SILHOUETTE", "Oversized top with wide-leg bottoms creates a heavy silhouette outside streetwear styling.", 2, [primaryTop.id, bottom.id]),
        );
      }
    }
    if (bottom.silhouette === "skinny" && shoe && /chunky|oversized|platform|boot/i.test(`${shoe.item.name} ${shoe.item.subcategory ?? ""}`)) {
      warnings.push(
        warn("SKINNY_BOTTOM_CHUNKY_SHOE", `Skinny "${bottom.item.name}" with bulky footwear "${shoe.item.name}" can skew proportions.`, 2, [bottom.id, shoe.id]),
      );
    }
  }

  // Short bottoms with formal/heavy shoes on formal/business/smart-casual occasions
  if (bottom && bottom.length === "short" && shoe && ["boots", "loafers", "heels"].includes(shoe.type)) {
    if (dc === "smart_casual" || dc === "business" || dc === "formal" || shoe.type === "boots") {
      warnings.push(
        warn("SHORTS_FOOTWEAR_MISMATCH", `Pairing "${bottom.item.name}" with "${shoe.item.name}" is awkward for this setting.`, 2, [bottom.id, shoe.id]),
      );
    }
  }

  const rawLoad = warnings.reduce((sum, w) => sum + w.severity, 0);
  const maxAllowedLoad = ctx.constraints.allowBold ? 5 : isStreetwearContext ? 3 : 2;
  const ok = hardViolations.length === 0 && rawLoad <= maxAllowedLoad;

  return {
    ok,
    archetype,
    hard: hardViolations,
    warnings,
    warningLoad: rawLoad,
  };
}
